class Animal {
  constructor(name) {
    this.name = name;
  }

  speak() {
    console.log(`${this.name} makes a noise.`);
  }
}

// Inheritance
class Dog extends Animal {
  constructor(name, breed) {
    super(name); // Call the parent constructor
    this.breed = breed;
  }

  speak() {
    console.log(`${this.name} barks!`);
  }

  // Static method (belongs to the class, not the dog)
  static info() {
    console.log("Dogs are great pets.");
  }
}

const d = new Dog('Rex', 'German Shepherd');
d.speak(); // "Rex barks!"
console.log(d.breed); // "German Shepherd"

Dog.info(); // "Dogs are great pets."
